{
  "name": "model-router",
  "version": "0.11.0",
  "description": "Routes each subagent to the cheapest Claude model and effort that can do its task, judged by TypeSafe Jev. On every Agent call it sends the subagent's task text, condensed and with secrets masked, to api.typesafe.ai with your TypeSafe key.",
  "author": {
    "name": "Akurganow",
    "url": "https://github.com/Akurganow"
  },
  "license": "MIT",
  "homepage": "https://github.com/Akurganow/model-router",
  "repository": "https://github.com/Akurganow/model-router",
  "privacyPolicyUrl": "https://github.com/Akurganow/model-router/blob/main/plugins/model-router/PRIVACY.md",
  "keywords": [
    "claude-code",
    "mod",
    "subagents",
    "model-routing",
    "typesafe",
    "jev"
  ],
  "userConfig": {
    "api_key": {
      "type": "string",
      "title": "TypeSafe API key",
      "description": "Your TypeSafe API key. The plugin sends it to TypeSafe only, as the bearer token of the scoring request. The README says where to get one.",
      "sensitive": true
    },
    "model": {
      "type": "string",
      "title": "Jev model",
      "description": "jev-latest: the most recent official Jev release. jev-preview: the most recent release, official or not. Both are TypeSafe aliases that move when a new release ships.",
      "options": [
        "jev-latest",
        "jev-preview"
      ],
      "default": "jev-latest"
    }
  }
}
